choose.when:
SELECT us.user_name, us.nick_name, us.user_id, us.role_id, us.sex, us.phonenumber, us.organization_id, r.role_name FROM sys_user_role u LEFT JOIN sys_role r ON r.role_id = u.role_id LEFT JOIN sys_user us ON us.user_id = u.user_id WHERE u.user_id IN (SELECT user_id FROM tb_project_member WHERE project_id = #{projectId,jdbcType=BIGINT})
AND u.role_id = #{roleId,jdbcType=BIGINT}
AND us.sex = #{sex,jdbcType=INTEGER}
AND us.organization_id = #{organizationId,jdbcType=BIGINT}
AND us.user_name like concat('%', #{userName}, '%')
AND us.nick_name like concat('%', #{nickName}, '%')

